Let us define the following classes of functions from $\Z=\X\times \Y$ to $\R$:
\begin{equation}\label{eq:Ek}
	\forall k\in [C],\quad \mathcal{E}_k = \{ e_k \in \R^{\Z} : e_k(x,y) = y-\bar{f}_k(x),\ \bar{f}_k \in \bar{\F_k}\}.
\end{equation}
By using the facts that for any $(a_k)_{1\leq k\leq C} \in\R^C$, $\min_{k\in[C]} a_k = -\max_{k\in[C]} -a_k$ and that $\sigma_i$ and $-\sigma_i$ share the same distribution, we have:
\begin{align*}
	\mathcal{R}_n&\left( \L_{p,\F^S}^S \right) \nonumber\\
	&= \E_{\g X_n \g Y_n \g \sigma_n} \sup_{\bar{f} \in \bar{\F^S}} \frac{1}{n} \sum_{i=1}^n \sigma_i \min_{k\in[C]} |Y_i - \bar{f}_k(X_i ) |^p \\
	&= \E_{\g X_n \g Y_n \g \sigma_n} \sup_{\bar{f} \in \bar{\F^S}}  \frac{1}{n} \sum_{i=1}^n - \sigma_i \max_{k\in[C]} -|Y_i -\bar{f}_k(X_i ) |^p \\
	&= \E_{\g X_n \g Y_n \g \sigma_n} \sup_{\bar{f} \in \bar{\F^S}}  \frac{1}{n} \sum_{i=1}^n \sigma_i \max_{k\in[C]} - |Y_i - \bar{f}_k(X_i ) |^p \\
	&= \E_{\g X_n \g Y_n \g \sigma_n} \sup_{(e_k \in \mathcal{E}_k)_{k\in[C]}}  \frac{1}{n} \sum_{i=1}^n \sigma_i \max_{k\in[C]} - |e_k(X_i,Y_i)|^p \\
	&\leq \sum_{k=1}^C \mathcal{R}_n( -|\mathcal{E}_k|^p ) ,
\end{align*}
where the inequality is obtained by application of Lemma~\ref{lem:mohri} in Appendix~\ref{sec:tools}. 
By taking into account the range of $|\mathcal{E}_k|$, i.e., $[0 , 1]$, and the Lipschitz constant of $\phi(u)=u^p$ for $u$ in that interval, we obtain by contraction (Lemma~\ref{lem:contraction}) that $\mathcal{R}_n( -|\mathcal{E}_k|^p) \leq p\mathcal{R}_n( \mathcal{E}_k )$. Then, following the last steps of the proof of Theorem~\ref{thm:real} (Appendix~\ref{sec:proofreal}) leads to
\begin{align*}
	\mathcal{R}_n( \mathcal{E}_k) \leq \mathcal{R}_n(\bar{\F_k})\leq \mathcal{R}_n(\F_k), 
\end{align*}
which completes the proof.

